INSERT INTO question (id,bank_type,category,title,content,answer,flag,score,difficulty,writeup,status,ext,deleted,created_at,updated_at) VALUES (9300000000000000004,'CTF','CRYPTO','Crypto4','rsa基础',NULL,'flag{1e257b39a25c6a7c4d66e197}',200,'MEDIUM','# 题目：Crypto4

### 题目描述：rsa基础

