INSERT INTO question (id,bank_type,category,title,content,answer,flag,score,difficulty,writeup,status,ext,deleted,created_at,updated_at) VALUES (9300000000000000006,'CTF','CRYPTO','Crypto6','Not only base??',NULL,'flag{N0t_0NLy_b4sE32}',100,'EASY','# 题目：Crypto2

